{
  "lecture": [
    {
      "etiquette": "F06",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de composantes plantées vraies couvertes par l'oracle (D2 sur les retenues) augmente d'au moins 25 %, sans hausse des fausses découvertes."
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle (composantes plantées couvertes dans les propositions brutes et dans les retenues, fausses promotions)"
      },
      "R3": {
        "valeur": 1,
        "passage": "Aucune modification de l'archive servie (aucun masquage)."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "effectuer 6 appels parallèles et indépendants en sessions neuves sans historique par proposeur et par génération, la consigne de chaque appel demandant exactement 1 carte."
      },
      "R6": {
        "valeur": 1,
        "passage": "quelques dizaines de dollars d'appels pour comparer la couverture oracle de 6 appels d'une carte contre 1 appel de 6 cartes à coût égal."
      },
      "R7": {
        "valeur": 1,
        "passage": "Exploite la propriété de réinitialisation de contexte pour éviter l'effondrement sur un bassin d'idées unique lors de la génération autorégressive séquentielle de plusieurs cartes."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F07",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de composantes plantées vraies de profondeur 2 couvertes au sens de l'oracle dans les retenues augmente d'au moins 30 %"
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle (nombre total de composantes plantées vraies couvertes dans les retenues, en particulier les composantes conditionnelles de profondeur 2, et nombre de lois fausses ou copies promues)"
      },
      "R3": {
        "valeur": 0,
        "motif": "L'arrêt de la course et l'ouverture de générations supplémentaires dépendent des retenues du juge, utilisant ainsi son verdict pour sélectionner les appels futurs aux proposeurs, sans justifier une réouverture de cette interdiction."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:cout"
      },
      "R5": {
        "valeur": 1,
        "passage": "Si plus de 80 % des cartes valides de cette première moitié sont déjà dans le nul des lois de l'archive (au sens du seuil epsilon du regroupement des doublons), appeler la seconde moitié des proposeurs"
      },
      "R6": {
        "valeur": 1,
        "passage": "sur processeur seul (zéro dépense nouvelle) en simulant sur les traces des courses passées (comme v67) la règle d'économie de la moitié des proposeurs"
      },
      "R7": {
        "valeur": 1,
        "passage": "Aligne la dépense séquentielle sur la structure causale des mondes à chaînes conditionnelles"
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F08",
      "R1": {
        "valeur": 1,
        "passage": "La couverture des composantes vraies ne baisse pas de plus de 5 % en relatif, à tirages frais égaux."
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle : copies promues, composantes vraies couvertes, composantes conditionnelles absorbées. Coût : heures de processeur du juge, la classe étant plus grande."
      },
      "R3": {
        "valeur": 1,
        "passage": "Le dénominateur est le maximum de vraisemblance sur la classe élargie. Le reste du juge est inchangé. La preuve de validité est scellée avant toute course."
      },
      "R4": {
        "valeur": 0,
        "motif": "La fiche affirme conserver la garantie, mais ne nomme ni la borne d'espérance des valeurs e, ni le contrôle des comparaisons multiples, ni une garantie équivalente précise contre le nul élargi."
      },
      "R5": {
        "valeur": 1,
        "passage": "La classe du nul reçoit, pour chaque paire de lois prises parmi l'archive et les lois aveugles, chaque trait public et chaque décile public, la loi par morceaux de profondeur 1."
      },
      "R6": {
        "valeur": 1,
        "passage": "Quelques heures de processeur. Aucun appel de modèle."
      },
      "R7": {
        "valeur": 1,
        "passage": "la garde contre les copies est fermée à l'endroit exact où une pression vers la variété fait passer des copies."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F09",
      "R1": {
        "valeur": 1,
        "passage": "à budget de tirages égal, au moins 20 % de composantes plantées couvertes en plus par génération que l'ordre actuel"
      },
      "R2": {
        "valeur": 1,
        "passage": "composantes plantées couvertes par génération (oracle, lu après la course) ; témoin à coût égal : ordre tiré au hasard"
      },
      "R3": {
        "valeur": 0,
        "motif": "Les cotes produites par des juges à modèle déterminent quelles cartes accèdent au test de mort avant épuisement du budget, introduisant un score de juge dans la sélection."
      },
      "R4": {
        "valeur": 0,
        "motif": "Aucune garantie statistique conservée ni aucun nul correspondant ne sont précisés."
      },
      "R5": {
        "valeur": 0,
        "motif": "Le tournoi n'est pas exécutable sans préciser notamment le nombre de comparaisons, la mise à jour des cotes et la règle de choix des paires."
      },
      "R6": {
        "valeur": 1,
        "passage": "quelques dollars de juges par génération"
      },
      "R7": {
        "valeur": 0,
        "motif": "Qualifier les cartes bien cotées de prometteuses ne fournit aucun mécanisme reliant la préférence des juges à une meilleure couverture mesurée par l'oracle."
      },
      "N": {
        "valeur": "C1",
        "passage_fiche": "Chaque carte d'une génération reçoit une cote Elo (1 200 au départ). Des juges à modèle comparent les cartes deux à deux : les mieux classées en débats à plusieurs tours, les autres en une seule comparaison ; les paires sont choisies de préférence entre cartes semblables, selon un graphe de proximité.",
        "passage_catalogue": "Un agent de classement tient un **tournoi à cotes Elo** (1 200 au départ) entre hypothèses, par **comparaisons appariées** : débats à plusieurs tours pour les mieux classées, une seule comparaison pour les autres ; les paires sont tirées de préférence entre hypothèses semblables (graphe d'un agent de proximité) ; le classement oriente l'évolution des hypothèses."
      }
    },
    {
      "etiquette": "F10",
      "R1": {
        "valeur": 1,
        "passage": "au moins 20 % de cartes promues par dollar en plus à la sixième génération qu'avec des parts égales"
      },
      "R2": {
        "valeur": 0,
        "motif": "La métrique compte les promotions du juge statistique par dollar, et non les composantes vraies, les lois fausses ou les copies identifiées par l'oracle."
      },
      "R3": {
        "valeur": 0,
        "motif": "La composition budgétaire des proposeurs dépend directement de leurs promotions par le juge statistique, contrairement à l'interdiction de sélectionner la composition sur son verdict."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:composition"
      },
      "R5": {
        "valeur": 0,
        "motif": "La règle ne précise ni comment combiner proportionnalité et plancher de 5 %, ni comment répartir le budget lorsqu'aucune carte n'est promue."
      },
      "R6": {
        "valeur": 0,
        "motif": "Un témoin à coût égal est nommé, mais le rejeu sur journaux n'est accompagné d'aucun ordre de grandeur du coût de l'expérience."
      },
      "R7": {
        "valeur": 0,
        "motif": "L'affirmation générique que le budget va là où il rend le plus n'explique pas pourquoi le rendement passé en promotions prédirait un meilleur rendement à la sixième génération."
      },
      "N": {
        "valeur": "aucune"
      }
    }
  ]
}
